package com.example.takura.communications;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import com.example.takura.communications.application.*;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.*;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;
class SesEventServiceTest{@Test void forgedEnvelopeIsRejectedBeforeDatabaseMutation(){JdbcTemplate jdbc=mock(JdbcTemplate.class);var service=new SesEventService(jdbc,new ObjectMapper(),Clock.fixed(Instant.parse("2026-10-21T10:00:00Z"),ZoneOffset.UTC),e->false,"arn:aws:sns:af-south-1:123456789012:takura-production");byte[] body="{\"TopicArn\":\"arn:aws:sns:af-south-1:123456789012:takura-production\",\"MessageId\":\"forged\"}".getBytes();assertThatThrownBy(()->service.accept(body)).isInstanceOf(SecurityException.class).hasMessageContaining("SNS_SIGNATURE_INVALID");verifyNoInteractions(jdbc);}@Test void wrongTopicIsRejectedEvenWithFixtureVerifier(){JdbcTemplate jdbc=mock(JdbcTemplate.class);var service=new SesEventService(jdbc,new ObjectMapper(),Clock.systemUTC(),e->true,"expected");assertThatThrownBy(()->service.accept("{\"TopicArn\":\"other\"}".getBytes())).isInstanceOf(SecurityException.class);verifyNoInteractions(jdbc);}}
